from pathlib import Path

# ---------- Storefront ----------
p = Path('index.html')
s = p.read_text()

old_import = "import { getFirestore, collection, onSnapshot, doc, writeBatch, serverTimestamp, setDoc, query, where } from 'https://www.gstatic.com/firebasejs/12.16.0/firebase-firestore.js';"
new_import = "import { getFirestore, collection, onSnapshot, doc, serverTimestamp, setDoc, query, where, runTransaction } from 'https://www.gstatic.com/firebasejs/12.16.0/firebase-firestore.js';"
if old_import not in s:
    raise SystemExit('storefront firestore import marker missing')
s = s.replace(old_import, new_import, 1)

old_order = "window.placeOrder=async()=>{const rows=cartRows();if(!rows.length)return;const customer={name:coName.value.trim(),phone:coPhone.value.trim(),city:coCity.value.trim(),address:coAddress.value.trim()};if(!customer.name||!customer.phone||!customer.address){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent='أدخل الاسم والهاتف والعنوان.';return}const isTransfer=coPayment.value==='transfer',proofFile=coProof.files?.[0]||null;if(isTransfer&&!proofFile){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent='ارفع صورة إثبات التحويل البنكي قبل تأكيد الطلب.';return}const items=rows.map(({p,qty})=>({productId:String(p.id),name:String(p.name||''),price:Number(p.price||0),qty,image:Array.isArray(p.images)&&p.images[0]?String(p.images[0]):''}));const total=items.reduce((s,x)=>s+x.price*x.qty,0),orderNo='MO-'+String(Date.now()).slice(-6);placeOrderBtn.disabled=true;placeOrderBtn.textContent=isTransfer?'جاري رفع الإثبات...':'جاري الإرسال...';try{const paymentProofUrl=isTransfer?await uploadPaymentProof(proofFile):'';if(isTransfer)placeOrderBtn.textContent='جاري تسجيل الطلب...';const orderRef=doc(collection(db,'orders')),batch=writeBatch(db);batch.set(orderRef,{orderNo,customerUid:currentUser.uid,customerEmail:currentUser.email||'',customer,items,total,payment:coPayment.value,paymentProofUrl,status:'new',createdAt:serverTimestamp()});batch.set(doc(db,'orderTracking',orderRef.id),{orderNo,customerUid:currentUser.uid,status:'new',estimatedDelivery:'',updatedAt:serverTimestamp()});await batch.commit();localStorage.setItem('MauriOne_account',JSON.stringify(customer));orderHistory.unshift({id:orderRef.id,orderNo,customerUid:currentUser.uid,items,total,payment:coPayment.value,status:'new',estimatedDelivery:'',updatedAt:new Date().toLocaleString('ar'),createdAt:Date.now()});saveOrders();connectTracking();cart=[];saveCart();updateBadge();renderCart();renderMyOrders();checkoutStatus.style.display='block';checkoutStatus.className='notice success';checkoutStatus.textContent=(isTransfer?'تم تسجيل طلبك وإرفاق إثبات التحويل. ':'تم تسجيل طلبك بنجاح. ')+'يمكنك متابعة الطلب من قسم «طلباتي» في السلة. رقم الطلب: '+orderNo;placeOrderBtn.style.display='none'}catch(e){console.error(e);checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent='تعذر إرسال الطلب. حاول مرة أخرى.'}finally{placeOrderBtn.disabled=false;placeOrderBtn.textContent='تأكيد الطلب'}};"

new_order = """window.placeOrder=async()=>{const rows=cartRows();if(!rows.length)return;if(!currentUser){openStore('accountPage','navAccount');return}const customer={name:coName.value.trim(),phone:coPhone.value.trim(),city:coCity.value.trim(),address:coAddress.value.trim()};if(!customer.name||!customer.phone||!customer.address){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent='أدخل الاسم والهاتف والعنوان.';return}const isTransfer=coPayment.value==='transfer',proofFile=coProof.files?.[0]||null;if(isTransfer&&!proofFile){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent='ارفع صورة إثبات التحويل البنكي قبل تأكيد الطلب.';return}const items=rows.map(({p,qty})=>({productId:String(p.id),name:String(p.name||''),price:Number(p.price||0),qty:Number(qty||1),image:Array.isArray(p.images)&&p.images[0]?String(p.images[0]):''}));const total=items.reduce((sum,x)=>sum+x.price*x.qty,0),orderNo='MO-'+String(Date.now()).slice(-6);placeOrderBtn.disabled=true;placeOrderBtn.textContent=isTransfer?'جاري رفع الإثبات...':'جاري التحقق من المخزون...';try{const paymentProofUrl=isTransfer?await uploadPaymentProof(proofFile):'';placeOrderBtn.textContent='جاري حجز الكمية وتسجيل الطلب...';const orderRef=doc(collection(db,'orders')),trackingRef=doc(db,'orderTracking',orderRef.id),productRefs=items.map(i=>doc(db,'products',i.productId));await runTransaction(db,async tx=>{const snaps=[];for(const ref of productRefs)snaps.push(await tx.get(ref));const updates=[];for(let i=0;i<items.length;i++){const item=items[i],snap=snaps[i];if(!snap.exists())throw new Error('STOCK|'+item.name+'|0');const available=Number(snap.data().stock||0);if(!Number.isFinite(available)||available<item.qty)throw new Error('STOCK|'+item.name+'|'+Math.max(0,available||0));updates.push({ref:productRefs[i],stock:available-item.qty})}tx.set(orderRef,{orderNo,customerUid:currentUser.uid,customerEmail:currentUser.email||'',customer,items,total,payment:coPayment.value,paymentProofUrl,status:'new',inventoryManaged:true,createdAt:serverTimestamp()});tx.set(trackingRef,{orderNo,customerUid:currentUser.uid,status:'new',estimatedDelivery:'',updatedAt:serverTimestamp()});updates.forEach(u=>tx.update(u.ref,{stock:u.stock,updatedAt:serverTimestamp()}))});localStorage.setItem('MauriOne_account',JSON.stringify({...account(),...customer,uid:currentUser.uid,email:currentUser.email||''}));orderHistory.unshift({id:orderRef.id,orderNo,customerUid:currentUser.uid,items,total,payment:coPayment.value,status:'new',inventoryManaged:true,estimatedDelivery:'',updatedAt:new Date().toLocaleString('ar'),createdAt:Date.now()});saveOrders();connectTracking();cart=[];saveCart();updateBadge();renderCart();renderMyOrders();checkoutStatus.style.display='block';checkoutStatus.className='notice success';checkoutStatus.textContent=(isTransfer?'تم تسجيل طلبك وإرفاق إثبات التحويل. ':'تم تسجيل طلبك بنجاح. ')+'تم حجز الكمية من المخزون. رقم الطلب: '+orderNo;placeOrderBtn.style.display='none'}catch(e){console.error(e);checkoutStatus.style.display='block';checkoutStatus.className='notice';const m=String(e?.message||'');if(m.startsWith('STOCK|')){const parts=m.split('|');checkoutStatus.textContent='الكمية المطلوبة من «'+(parts[1]||'المنتج')+'» غير متوفرة الآن. المتوفر: '+Number(parts[2]||0);renderCart()}else if(e?.code==='permission-denied'){checkoutStatus.textContent='تعذر حجز المخزون. يجب تحديث صلاحيات Firestore الخاصة بالمخزون.'}else checkoutStatus.textContent='تعذر إرسال الطلب. حاول مرة أخرى.'}finally{placeOrderBtn.disabled=false;placeOrderBtn.textContent='تأكيد الطلب'}};"""

if old_order not in s:
    raise SystemExit('storefront placeOrder marker missing')
s = s.replace(old_order, new_order, 1)
p.write_text(s)

# ---------- Admin ----------
p = Path('admin.html')
s = p.read_text()

old_admin_import = "import{getFirestore,collection,doc,addDoc,onSnapshot,serverTimestamp,writeBatch,setDoc}from'https://www.gstatic.com/firebasejs/12.16.0/firebase-firestore.js';"
new_admin_import = "import{getFirestore,collection,doc,addDoc,onSnapshot,serverTimestamp,writeBatch,setDoc,runTransaction}from'https://www.gstatic.com/firebasejs/12.16.0/firebase-firestore.js';"
if old_admin_import not in s:
    raise SystemExit('admin firestore import marker missing')
s = s.replace(old_admin_import, new_admin_import, 1)

old_progress = "window.saveProgress=async id=>{const o=orders.find(x=>x.id===id);if(!o)return;const st=$('st').value,eta=$('eta').value||'',btn=$('saveProgress'),msg=$('progressMsg');btn.disabled=true;msg.textContent='جاري الحفظ...';try{const b=writeBatch(db);b.update(doc(db,'orders',id),{status:st,estimatedDelivery:eta,updatedAt:serverTimestamp()});b.set(doc(db,'orderTracking',id),{orderNo:o.orderNo||id,status:st,estimatedDelivery:eta,updatedAt:serverTimestamp()},{merge:true});await b.commit();o.status=st;o.estimatedDelivery=eta;render();if(st==='delivered'){msg.className='ok';msg.textContent='تم التسليم ونُقل الطلب إلى الطلبات المكتملة.';setTimeout(()=>{closeOrder();openPage('orders','navOrders')},300)}else{msg.className='ok';msg.textContent='تم الحفظ وسيظهر للزبون.'}}catch(e){msg.textContent='تعذر الحفظ: '+e.message}finally{btn.disabled=false}};"

new_progress = """window.saveProgress=async id=>{const o=orders.find(x=>x.id===id);if(!o)return;const st=$('st').value,eta=$('eta').value||'',btn=$('saveProgress'),msg=$('progressMsg');btn.disabled=true;msg.className='';msg.textContent='جاري الحفظ...';try{await runTransaction(db,async tx=>{const orderRef=doc(db,'orders',id),orderSnap=await tx.get(orderRef);if(!orderSnap.exists())throw new Error('الطلب غير موجود');const live={id,...orderSnap.data()};if(live.status==='cancelled'&&st!=='cancelled')throw new Error('الطلب الملغي نهائي. أنشئ طلبًا جديدًا بدل إعادة فتحه حتى يبقى المخزون صحيحًا.');const shouldRestore=st==='cancelled'&&live.status!=='cancelled'&&live.inventoryManaged===true;const itemRows=Array.isArray(live.items)?live.items.filter(i=>i?.productId&&Number(i.qty||0)>0):[];const productRows=[];if(shouldRestore){for(const item of itemRows){const ref=doc(db,'products',String(item.productId)),snap=await tx.get(ref);if(snap.exists())productRows.push({ref,stock:Number(snap.data().stock||0),qty:Number(item.qty||0)})}}tx.update(orderRef,{status:st,estimatedDelivery:eta,updatedAt:serverTimestamp()});tx.set(doc(db,'orderTracking',id),{orderNo:live.orderNo||id,status:st,estimatedDelivery:eta,updatedAt:serverTimestamp()},{merge:true});if(shouldRestore)productRows.forEach(p=>tx.update(p.ref,{stock:p.stock+p.qty,updatedAt:serverTimestamp()}))});o.status=st;o.estimatedDelivery=eta;render();msg.className='ok';if(st==='cancelled'&&o.inventoryManaged===true)msg.textContent='تم إلغاء الطلب وإعادة الكمية إلى المخزون.';else if(st==='delivered')msg.textContent='تم التسليم ونُقل الطلب إلى الطلبات المكتملة.';else msg.textContent='تم الحفظ وسيظهر للزبون.';if(st==='delivered'||st==='cancelled')setTimeout(()=>{closeOrder();openPage('orders','navOrders')},450)}catch(e){msg.textContent='تعذر الحفظ: '+(e.message||e)}finally{btn.disabled=false}};"""

if old_progress not in s:
    raise SystemExit('admin saveProgress marker missing')
s = s.replace(old_progress, new_progress, 1)
p.write_text(s)

print('inventory automation applied')
